 },
 {
  "id": "L699-796_n004",
  "establishes": "The commentary strongly advises developers to put untrusted data in untrusted_text blocks when available, and otherwise use YAML, JSON, or XML format, with the choice between these formats depending on considerations of readability and escaping.",
